/**
 * Automatic App Exit Cache & Generated File Cleaner
 *
 * Ensures that every time the user exits/closes the app (beforeunload, pagehide, unload)
 * or triggers a manual purge, all cached files, Blob URLs, IndexedDB databases
 * (including lr_verified_blobs), Cache Storage API entries, Origin Private File System (OPFS)
 * entries, sessionStorage, and localStorage generated by the app are completely deleted.
 */

export interface CachePurgeStats {
  revokedBlobUrls: number;
  deletedIndexedDbCount: number;
  deletedCacheStorageCount: number;
  clearedStorageKeys: number;
  timestamp: string;
}

const activeBlobUrls = new Set<string>();
let totalGeneratedBlobCount = 0;
let isHookInstalled = false;
let listenersChangeCallback: (() => void) | null = null;

function notifyChange() {
  if (listenersChangeCallback) {
    listenersChangeCallback();
  }
}

/**
 * Intercepts URL.createObjectURL and URL.revokeObjectURL so every generated
 * file/blob URL created anywhere in the app is tracked and guaranteed to be
 * revoked upon exit.
 */
export function installBlobUrlTracker(onChange?: () => void): void {
  if (onChange) {
    listenersChangeCallback = onChange;
  }
  if (isHookInstalled || typeof window === 'undefined' || !window.URL) {
    return;
  }
  isHookInstalled = true;

  const originalCreateObjectURL = URL.createObjectURL.bind(URL);
  const originalRevokeObjectURL = URL.revokeObjectURL.bind(URL);

  URL.createObjectURL = (obj: Blob | MediaSource): string => {
    const url = originalCreateObjectURL(obj);
    activeBlobUrls.add(url);
    totalGeneratedBlobCount += 1;
    notifyChange();
    return url;
  };

  URL.revokeObjectURL = (url: string): void => {
    activeBlobUrls.delete(url);
    originalRevokeObjectURL(url);
    notifyChange();
  };
}

/**
 * Returns current session cache tracking metrics.
 */
export function getSessionCacheInfo(): {
  activeBlobUrlsCount: number;
  totalGeneratedFilesCount: number;
} {
  return {
    activeBlobUrlsCount: activeBlobUrls.size,
    totalGeneratedFilesCount: totalGeneratedBlobCount,
  };
}

/**
 * Synchronously revokes all tracked Blob URLs and clears Web Storage (localStorage & sessionStorage),
 * and sends a synchronous signal to any active Service Worker to wipe Cache Storage even after tab close.
 */
export function purgeSyncOnAppExit(): number {
  let revokedCount = 0;

  // 1. Revoke all active Blob URLs generated by PDF, Excel, CSV, JSON, or ZIP exports
  if (typeof URL !== 'undefined' && URL.revokeObjectURL) {
    for (const url of Array.from(activeBlobUrls)) {
      try {
        URL.revokeObjectURL(url);
        revokedCount++;
      } catch {
        // Ignore errors during unload
      }
    }
    activeBlobUrls.clear();
  }

  // 2. Clear sessionStorage and localStorage
  try {
    if (typeof sessionStorage !== 'undefined') {
      sessionStorage.clear();
    }
  } catch {
    // Ignore restricted storage errors
  }

  try {
    if (typeof localStorage !== 'undefined') {
      localStorage.clear();
    }
  } catch {
    // Ignore restricted storage errors
  }

  // 3. Instruct Service Worker to purge all Cache Storage & IndexedDB entries in background
  try {
    if (typeof navigator !== 'undefined' && 'serviceWorker' in navigator && navigator.serviceWorker.controller) {
      navigator.serviceWorker.controller.postMessage({
        type: 'PURGE_ALL_APP_CACHES',
      });
    }
  } catch {
    // Ignore service worker postMessage errors
  }

  // 4. Fire non-blocking IndexedDB & Cache API deletion requests
  try {
    if (typeof indexedDB !== 'undefined') {
      const knownDbs = ['lr_verified_blobs', 'LR_Master_Ledger_DB', 'lrgetbd_cache', 'keyval-store'];
      for (const dbName of knownDbs) {
        try {
          indexedDB.deleteDatabase(dbName);
        } catch {
          // Ignore
        }
      }
      if ('databases' in indexedDB && typeof indexedDB.databases === 'function') {
        indexedDB
          .databases()
          .then((dbs) => {
            dbs.forEach((db) => {
              if (db.name) {
                indexedDB.deleteDatabase(db.name);
              }
            });
          })
          .catch(() => {});
      }
    }
  } catch {
    // Ignore IndexedDB errors
  }

  try {
    if (typeof caches !== 'undefined') {
      caches
        .keys()
        .then((keys) => {
          keys.forEach((key) => {
            caches.delete(key);
          });
        })
        .catch(() => {});
    }
  } catch {
    // Ignore Cache Storage errors
  }

  totalGeneratedBlobCount = 0;
  notifyChange();
  return revokedCount;
}

/**
 * Full asynchronous purge of all cached files, Blob URLs, IndexedDB databases,
 * Cache Storage buckets, Origin Private File System (OPFS), localStorage, and sessionStorage.
 */
export async function purgeAllAppGeneratedCaches(): Promise<CachePurgeStats> {
  let clearedStorageKeys = 0;
  try {
    if (typeof localStorage !== 'undefined') {
      clearedStorageKeys += localStorage.length;
    }
    if (typeof sessionStorage !== 'undefined') {
      clearedStorageKeys += sessionStorage.length;
    }
  } catch {
    // Ignore
  }

  const revokedBlobUrls = purgeSyncOnAppExit();

  // Delete all IndexedDB databases
  let deletedIndexedDbCount = 0;
  if (typeof indexedDB !== 'undefined') {
    const dbNames = new Set<string>([
      'lr_verified_blobs',
      'LR_Master_Ledger_DB',
      'lrgetbd_cache',
      'keyval-store',
    ]);

    if ('databases' in indexedDB && typeof indexedDB.databases === 'function') {
      try {
        const dbs = await indexedDB.databases();
        for (const db of dbs) {
          if (db.name) dbNames.add(db.name);
        }
      } catch {
        // Ignore
      }
    }

    for (const name of dbNames) {
      try {
        await new Promise<void>((resolve) => {
          const req = indexedDB.deleteDatabase(name);
          req.onsuccess = () => {
            deletedIndexedDbCount++;
            resolve();
          };
          req.onerror = () => resolve();
          req.onblocked = () => resolve();
        });
      } catch {
        // Ignore
      }
    }
  }

  // Delete all Cache Storage API caches
  let deletedCacheStorageCount = 0;
  if (typeof caches !== 'undefined') {
    try {
      const keys = await caches.keys();
      for (const key of keys) {
        const deleted = await caches.delete(key);
        if (deleted) deletedCacheStorageCount++;
      }
    } catch {
      // Ignore
    }
  }

  // Clear Origin Private File System (OPFS) if any temporary files exist
  try {
    if (
      typeof navigator !== 'undefined' &&
      navigator.storage &&
      typeof navigator.storage.getDirectory === 'function'
    ) {
      const rootDir = (await navigator.storage.getDirectory()) as any;
      if (rootDir && typeof rootDir.entries === 'function') {
        for await (const [entryName] of rootDir.entries()) {
          try {
            await rootDir.removeEntry(entryName, { recursive: true });
          } catch {
            // Ignore individual entry removal failure
          }
        }
      }
    }
  } catch {
    // Ignore OPFS errors
  }

  totalGeneratedBlobCount = 0;
  notifyChange();

  return {
    revokedBlobUrls,
    deletedIndexedDbCount,
    deletedCacheStorageCount,
    clearedStorageKeys,
    timestamp: new Date().toLocaleTimeString('bn-BD'),
  };
}

/**
 * Registers automatic cleanup listeners so whenever the user exits or closes the app
 * (beforeunload, pagehide, unload), all generated cached files are immediately deleted.
 */
export function registerExitCacheCleanup(onChange?: () => void): () => void {
  installBlobUrlTracker(onChange);

  // Also purge any stale leftover caches from any prior session on boot
  void purgeAllAppGeneratedCaches();

  const handleExit = () => {
    purgeSyncOnAppExit();
  };

  window.addEventListener('beforeunload', handleExit);
  window.addEventListener('pagehide', handleExit);
  window.addEventListener('unload', handleExit);

  return () => {
    window.removeEventListener('beforeunload', handleExit);
    window.removeEventListener('pagehide', handleExit);
    window.removeEventListener('unload', handleExit);
  };
}
